(function(){
  var e=function(a){return document.getElementById(a)};
  var c=function(s){return '$'+Math.round(s).toLocaleString('en-US')};
  var i=function(){var a=+e('r-inv').value,n=+e('r-min').value,o=+e('r-rate').value,t=+e('r-disc').value;
    e('o-inv').textContent=a.toLocaleString('en-US');e('o-min').textContent=n;e('o-rate').textContent='$'+o;e('o-disc').textContent=c(t);
    var l=a*n/60*.85;e('v-hours').textContent=Math.round(l).toLocaleString('en-US')+' h';e('v-year').textContent=c(l*o*12+t*.7*12);
    e('v-cost').textContent='$'+(n/60*o).toFixed(2);e('v-fte').textContent=(l/160).toFixed(1)+' FTE'};
  ['r-inv','r-min','r-rate','r-disc'].forEach(function(a){e(a).addEventListener('input',i)});i();
